insert into public.contents (id,slug,content_type,title,english_title,summary,aliases,review_status,publication_status,theme_links,discipline_ids,equipment_ids,primary_muscle_ids,secondary_muscle_ids,display_order,details) select id,slug,content_type,title,english_title,summary,aliases,review_status,publication_status,theme_links,discipline_ids,equipment_ids,primary_muscle_ids,secondary_muscle_ids,display_order,details from jsonb_to_recordset('[{"id": "sample-squat", "slug": "bodyweight-squat", "content_type": "exercise", "title": "徒手深蹲", "english_title": "Bodyweight Squat", "summary": "徒手深蹲的初版 3D 样本，用于体验观察和计划编辑，尚待专业动作审核。", "aliases": ["Bodyweight Squat", "徒手深蹲"], "review_status": "prototype", "publication_status": "draft", "theme_links": [{"theme": "gym", "sections": ["strength"]}, {"theme": "outdoor", "sections": ["bodyweight"]}, {"theme": "functional", "sections": ["circuit"]}], "discipline_ids": ["strength"], "equipment_ids": ["none"], "primary_muscle_ids": ["legs"], "secondary_muscle_ids": [], "display_order": 1, "details": {"tags": ["初版样本", "待专业审核"], "focus": ["观察髋部下降和回升的路径。", "暂停在底部，比较髋、膝与躯干的位置。", "检查双侧配合和脚部接触。"], "sections": [{"heading": "样本说明", "body": "此内容是产品与动作表现样本，不作为已审核的正式训练教程。训练参数由用户自行填写。"}], "motion": {"sample_id": "squat", "pattern": "01 / LOWER BODY", "phases": ["站立", "下蹲中", "底部"], "times": [0, 1, 2], "view": "angle", "orbit": "35deg 78deg 3.9m", "camera_target": "0m 0.85m 0.05m", "duration": 4}}}, {"id": "sample-push-up", "slug": "push-up", "content_type": "exercise", "title": "俯卧撑", "english_title": "Push-Up", "summary": "俯卧撑的初版 3D 样本，用于体验观察和计划编辑，尚待专业动作审核。", "aliases": ["Push-Up", "俯卧撑"], "review_status": "prototype", "publication_status": "draft", "theme_links": [{"theme": "gym", "sections": ["strength"]}, {"theme": "outdoor", "sections": ["bodyweight"]}, {"theme": "functional", "sections": ["circuit"]}], "discipline_ids": ["strength"], "equipment_ids": ["none"], "primary_muscle_ids": ["chest", "arms"], "secondary_muscle_ids": [], "display_order": 2, "details": {"tags": ["初版样本", "待专业审核"], "focus": ["观察躯干与下肢的整体起落。", "放慢观察屈肘时上臂的位置变化。", "检查手掌和脚尖的接触。"], "sections": [{"heading": "样本说明", "body": "此内容是产品与动作表现样本，不作为已审核的正式训练教程。训练参数由用户自行填写。"}], "motion": {"sample_id": "push-up", "pattern": "02 / HORIZONTAL PUSH", "phases": ["撑起", "下降中", "底部"], "times": [0, 1, 2], "view": "side", "orbit": "90deg 80deg 3.9m", "camera_target": "0m 0.32m -0.05m", "duration": 4}}}, {"id": "sample-dumbbell-curl", "slug": "dumbbell-curl", "content_type": "exercise", "title": "哑铃弯举", "english_title": "Dumbbell Curl", "summary": "哑铃弯举的初版 3D 样本，用于体验观察和计划编辑，尚待专业动作审核。", "aliases": ["Dumbbell Curl", "哑铃弯举"], "review_status": "prototype", "publication_status": "draft", "theme_links": [{"theme": "gym", "sections": ["strength"]}], "discipline_ids": ["strength"], "equipment_ids": ["dumbbell"], "primary_muscle_ids": ["arms"], "secondary_muscle_ids": [], "display_order": 3, "details": {"tags": ["初版样本", "待专业审核"], "focus": ["观察屈肘和伸肘的过程。", "暂停在顶部，比较上臂和躯干的位置。", "检查器械是否随手部运动。"], "sections": [{"heading": "样本说明", "body": "此内容是产品与动作表现样本，不作为已审核的正式训练教程。训练参数由用户自行填写。"}], "motion": {"sample_id": "dumbbell-curl", "pattern": "03 / ELBOW FLEXION", "phases": ["起始", "弯举中", "顶部"], "times": [0, 1, 2], "view": "angle", "orbit": "30deg 78deg 3.9m", "camera_target": "0m 0.85m 0.05m", "duration": 4}}}]'::jsonb) as seed(id text,slug text,content_type text,title text,english_title text,summary text,aliases text[],review_status text,publication_status text,theme_links jsonb,discipline_ids text[],equipment_ids text[],primary_muscle_ids text[],secondary_muscle_ids text[],display_order integer,details jsonb) on conflict(id) do nothing;
insert into public.media_assets (id,content_id,kind,bucket_id,object_path,mime_type,byte_size,sha256,attribution) select id,content_id,kind,bucket_id,object_path,mime_type,byte_size,sha256,attribution from jsonb_to_recordset('[{"id": "sample-squat-model", "content_id": "sample-squat", "kind": "model", "bucket_id": "exercise-media", "object_path": "samples/squat.glb", "mime_type": "model/gltf-binary", "byte_size": 5491640, "sha256": "bae9b8b383747110b20e5caea87970a49e2feb080c8616532766725d55aa3766", "attribution": {"human_geometry": "CC0 MakeHuman via OpenGym3D", "motion": "Original JY Fitness Atlas kinematic prototype", "review": "pending", "source_file": "site/backend/media/squat.glb"}}, {"id": "sample-squat-gif", "content_id": "sample-squat", "kind": "gif", "bucket_id": "exercise-media", "object_path": "samples/squat.gif", "mime_type": "image/gif", "byte_size": 361073, "sha256": "c1fd08ae79695c22384d43b6900013c0c6d50022a1f6fa54c69d6321f1a5b628", "attribution": {"human_geometry": "CC0 MakeHuman via OpenGym3D", "motion": "Original JY Fitness Atlas kinematic prototype", "review": "pending", "source_file": "site/backend/media/squat.gif"}}, {"id": "sample-push-up-model", "content_id": "sample-push-up", "kind": "model", "bucket_id": "exercise-media", "object_path": "samples/push-up.glb", "mime_type": "model/gltf-binary", "byte_size": 5491640, "sha256": "20a299cbad3091fb2dd25523d5af97de5712736666c0a991f8fe159855658757", "attribution": {"human_geometry": "CC0 MakeHuman via OpenGym3D", "motion": "Original JY Fitness Atlas kinematic prototype", "review": "pending", "source_file": "site/backend/media/push-up.glb"}}, {"id": "sample-push-up-gif", "content_id": "sample-push-up", "kind": "gif", "bucket_id": "exercise-media", "object_path": "samples/push-up.gif", "mime_type": "image/gif", "byte_size": 341507, "sha256": "49cae039e82666c29667d8d663a36af901f9cecc7e6352a34c6b16985526a69a", "attribution": {"human_geometry": "CC0 MakeHuman via OpenGym3D", "motion": "Original JY Fitness Atlas kinematic prototype", "review": "pending", "source_file": "site/backend/media/push-up.gif"}}, {"id": "sample-dumbbell-curl-model", "content_id": "sample-dumbbell-curl", "kind": "model", "bucket_id": "exercise-media", "object_path": "samples/dumbbell-curl.glb", "mime_type": "model/gltf-binary", "byte_size": 5500548, "sha256": "b38c7660c4c8b5770cfd2080edd044380d610671a76690c2cec682dc1fb7f7ef", "attribution": {"human_geometry": "CC0 MakeHuman via OpenGym3D", "motion": "Original JY Fitness Atlas kinematic prototype", "review": "pending", "source_file": "site/backend/media/dumbbell-curl.glb"}}, {"id": "sample-dumbbell-curl-gif", "content_id": "sample-dumbbell-curl", "kind": "gif", "bucket_id": "exercise-media", "object_path": "samples/dumbbell-curl.gif", "mime_type": "image/gif", "byte_size": 468992, "sha256": "3c37619a95f24d08b05d32e41d60dd0478c9b6859077c662a033b778990926d5", "attribution": {"human_geometry": "CC0 MakeHuman via OpenGym3D", "motion": "Original JY Fitness Atlas kinematic prototype", "review": "pending", "source_file": "site/backend/media/dumbbell-curl.gif"}}]'::jsonb) as seed(id text,content_id text,kind text,bucket_id text,object_path text,mime_type text,byte_size bigint,sha256 text,attribution jsonb) on conflict(id) do nothing;
